. "$PSScriptRoot\LockBitSingleSim-utilities.ps1";Assert-LBSafety -LabConfirmed:$LabConfirmed;$p=Initialize-LBEnvironment;$screen=Join-Path $p.Payloads 'screensaver.exe';$lock=Join-Path $p.Payloads '9689A16B72D48DAB.exe';New-LBDecoy $screen 'unused desktop-lock tool stand-in';New-LBDecoy $lock 'LockBit stand-in';Invoke-LBDecoy $screen 'screensaver.exe dropped but not used in attack' 'RDP desktop';Invoke-LBDecoy $lock '9689A16B72D48DAB.exe executed as LockBit' 'RDP desktop';$cmds=@('vssadmin delete shadows /all /quiet','wmic shadowcopy delete','bcdedit /set {default} bootstatuspolicy ignoreallfailures','bcdedit /set {default} recoveryenabled no','wbadmin delete catalog -quiet');foreach($c in $cmds){Invoke-LBDecoy $lock $c '9689A16B72D48DAB.exe'};Write-LBJson(Join-Path $p.Evidence 'recovery-commands.json')([ordered]@{reportedCommands=$cmds;screensaverUsed=$false;shadowCopiesDeleted=0;bootConfigurationChanged=0;recoveryConfigurationChanged=0;backupCatalogsDeleted=0}) impact-preparation;Write-LBJson(Join-Path $p.Evidence 'registry-markers.json')([ordered]@{reportStatesRegistryKeysCreated=$true;keyNames='not published in article text';registryValuesWritten=0}) persistence;Add-LBTimeline 30 execution 'screensaver and random-name LockBit tools represented; screensaver unused' @{liveMalware=$false};Add-LBTimeline 35 impact-preparation 'Shadow, boot, recovery, and backup-catalog commands represented' @{shadowCopiesDeleted=0;bootConfigurationChanged=0;backupCatalogsDeleted=0};Write-LBJson(Join-Path $p.Evidence 'phase2-negative.json')([ordered]@{liveMalware=0;shadowCopiesDeleted=0;bootConfigurationChanged=0;recoveryConfigurationChanged=0;backupCatalogsDeleted=0;registryValuesWritten=0}) safety
